/*
 * GSM USSD Query — Arduino Uno + SIM800/SIM900
 * Sends USSD codes (balance check, etc.) every 8 seconds and displays
 * the network response on the Serial Monitor.
 * Demonstrates AT+CUSD USSD command handling.
 */

#include <GSM.h>

GSM gsm;

String ussdCode = "*100#";
int queryCount = 0;

void setup() {
  Serial.begin(115200);
  while (!Serial);

  Serial.println("GSM USSD Client Starting...");

  // Initialize GSM module
  gsm.begin();

  // Check network registration
  Serial.println("AT+CREG?");
  Serial.println("AT+CSQ");

  Serial.println("GSM USSD Client ready!");
  Serial.println("USSD Code: " + ussdCode);
  Serial.println("---");
}

void loop() {
  queryCount++;

  Serial.print("Sending USSD query #");
  Serial.println(queryCount);

  gsm.sendUSSD(ussdCode);

  Serial.println("USSD query sent!");
  Serial.println("---");

  delay(8000);
}
